        </div>

        {/* HUD: AI Strategy Panel - Top Right */}
        <div className="absolute top-6 right-6 z-40 max-w-xs md:max-w-sm pointer-events-none transition-opacity duration-300">
            <div 
                className="bg-[#1e1e1e]/90 backdrop-blur-md p-5 rounded-[24px] border border-[#444746] shadow-xl"
                style={{ borderColor: aiRecommendedColor ? COLOR_CONFIG[aiRecommendedColor].hex : '#444746' }}
            >
                 <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                        <BrainCircuit className={`w-4 h-4 ${isAiThinking ? 'text-[#a8c7fa] animate-pulse' : 'text-[#c4c7c5]'}`} />
                        <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#8e918f]">
                            Gemini Live Strategy
                        </span>
                    </div>
                    {isAiThinking && <Loader2 className="w-3 h-3 animate-spin text-[#a8c7fa]" />}
                 </div>

                 <div className="space-y-2">
                     <p className="text-[#e3e3e3] font-bold text-sm md:text-base leading-snug">
                        {aiHint}
