         </p>
         <div className="mt-8 flex items-center gap-2 text-sm text-[#757575] uppercase tracking-wider font-bold">
           <div className="w-2 h-2 bg-[#42a5f5] rounded-full"></div>
           Please maximize window
         </div>
      </div>

      {/* FULL GAME AREA */}
      <div ref={gameContainerRef} className="flex-1 relative h-full overflow-hidden">
        <video ref={videoRef} className="absolute hidden" playsInline />
        <canvas ref={canvasRef} className="absolute inset-0" />

        {/* Loading Overlay */}
        {loading && (
            <div className="absolute inset-0 flex items-center justify-center bg-[#121212] z-50">
            <div className="flex flex-col items-center">
                <Loader2 className="w-12 h-12 text-[#42a5f5] animate-spin mb-4" />
                <p className="text-[#e3e3e3] text-lg font-medium">Initializing Camera...</p>
            </div>
            </div>
        )}

        {/* --- MAIN MENU --- */}
        {!loading && gameState === 'MENU' && (
            <div className="absolute inset-0 flex items-center justify-center bg-[#121212]/80 backdrop-blur-sm z-50 animate-in fade-in duration-500">
                <div className="bg-[#1e1e1e] p-8 rounded-[32px] border border-[#444746] shadow-2xl max-w-md w-full text-center">
                    <h1 className="text-4xl font-bold text-white mb-2 tracking-tight">Gemini Slingshot</h1>
                    <p className="text-[#c4c7c5] mb-8 text-sm">Select your challenge level</p>

