          },
          width: 1280,
          height: 720,
        });
        camera.start();
      }
    }

    return () => {
        if (camera) camera.stop();
        if (hands) hands.close();
    };
  }, [showTutorial]); // Updated dependency to pause loop effects if tutorial logic changes

