               <button onClick={() => { playSound('click'); setGameState('MENU'); gameStateRef.current = 'MENU'; }} className="md:hidden p-3 rounded-xl bg-[#2d2d2d] border border-[#444746] text-[#e3e3e3] shrink-0"> <MenuIcon className="w-5 h-5" /> </button>
