                   <div className="bg-transparent md:bg-[#2d2d2d] md:rounded-2xl md:p-4 md:border md:border-[#444746]"> <span className="text-xl md:text-3xl font-black text-white block"> <span className="md:hidden text-xs text-[#c4c7c5] mr-2">PTS</span> {score.toLocaleString()} </span> </div>
              </div>
              <div className="flex-1 md:flex-none space-y-0 md:space-y-2 flex flex-col justify-center">
                  <div className="hidden md:flex items-center justify-between"> <span className="text-xs text-[#c4c7c5] uppercase tracking-wider font-medium">Arsenal</span> <Crosshair className="w-3 h-3 text-[#c4c7c5]" /> </div>
                  <div className="flex md:grid md:grid-cols-3 gap-3 overflow-x-auto pb-1 md:pb-0 px-1 items-center">
                      {availableColors.length === 0 ? ( <p className="col-span-3 text-center text-xs text-gray-500 py-4 italic whitespace-nowrap">No ammo</p> ) : ( COLOR_KEYS.map(color => { const isAvailable = availableColors.includes(color); const isSelected = selectedColor === color; const config = COLOR_CONFIG[color]; return ( <button key={color} disabled={!isAvailable} onClick={() => { if(isAvailable) { playSound('click'); setSelectedColor(color); } }} className={`aspect-square rounded-xl flex items-center justify-center transition-all duration-200 relative shrink-0 ${!isAvailable ? 'opacity-20 cursor-not-allowed bg-[#2d2d2d]' : 'hover:scale-105'} ${isSelected ? 'ring-2 ring-white z-10 scale-105 w-10 h-10 md:w-auto md:h-auto' : 'border border-transparent w-8 h-8 md:w-auto md:h-auto'}`} style={{ backgroundColor: isAvailable ? '#2d2d2d' : undefined, borderColor: isSelected ? 'white' : '#444746' }}> {isAvailable && ( <div className="w-full h-full rounded-full transform scale-75" style={{ background: config.hex }} /> )} </button> ) }) )}
                  </div>
