  };

  const createFirework = (x: number, y: number) => {
      const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
      for (let i = 0; i < 50; i++) {
          const a = Math.random()*Math.PI*2; const s = Math.random()*8+3;
          particles.current.push({ x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s, life: 1.5+Math.random(), color: colors[Math.floor(Math.random()*colors.length)] });
      }
  };

  const spawnBubble = (row: number, col: number, width: number): Bubble => {
      const { x, y } = getBubblePos(row, col, width);
      let color = COLOR_KEYS[Math.floor(Math.random() * COLOR_KEYS.length)];
      let powerUp: PowerUpType | undefined = undefined;
      if (Math.random() < POWERUP_CHANCE) {
          const r = Math.random();
          if (r < 0.33) powerUp = 'bomb';
          else if (r < 0.66) powerUp = 'freeze';
          else { powerUp = 'wildcard'; color = 'rainbow'; }
      }
      return { id: `${row}-${col}-${Date.now()}-${Math.random()}`, row, col, x, y, color, active: true, powerUp };
  };

  const checkMatches = (startBubble: Bubble) => {
    const toCheck = [startBubble]; const visited = new Set<string>(); const matches: Bubble[] = [];
    const targetColor = startBubble.color; 
    while (toCheck.length > 0) {
      const current = toCheck.pop()!;
      if (visited.has(current.id)) continue;
      visited.add(current.id);
      if (current.color === targetColor || current.color === 'rainbow' || targetColor === 'rainbow') {
        matches.push(current);
        toCheck.push(...bubbles.current.filter(b => b.active && !visited.has(b.id) && isNeighbor(current, b)));
      }
    }
    if (matches.length >= 3) {
      matches.forEach(b => { 
          b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); 
          scoreRef.current += COLOR_CONFIG[b.color].points;
          if (b.powerUp === 'bomb') triggerBomb(b);
          if (b.powerUp === 'freeze') triggerFreeze();
      });
      playSound('pop'); setScore(scoreRef.current); dropFloating(); updateAvailableColors();
      if (bubbles.current.filter(b => b.active).length === 0) { setGameState('WIN'); gameStateRef.current = 'WIN'; playSound('win'); }
      return true;
    }
    return false;
  };

  const dropFloating = () => {
    const active = bubbles.current.filter(b => b.active); if (active.length === 0) return;
    const visited = new Set<string>(); const queue: Bubble[] = active.filter(b => b.row === 0);
    queue.forEach(b => visited.add(b.id)); let head = 0;
    while(head < queue.length){
        const curr = queue[head++];
        active.filter(b => !visited.has(b.id) && isNeighbor(curr, b)).forEach(b => { visited.add(b.id); queue.push(b); });
    }
    active.filter(b => !visited.has(b.id)).forEach(b => { b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); scoreRef.current += 50; });
  };

  const triggerBomb = (b: Bubble) => {
      playSound('bomb'); const r = layoutRef.current.bubbleRadius * 2.5;
      bubbles.current.filter(nb => nb.active && Math.hypot(nb.x-b.x, nb.y-b.y) < r).forEach(nb => { nb.active = false; createExplosion(nb.x, nb.y, '#fff'); scoreRef.current += 50; });
  };

  const triggerFreeze = () => { playSound('freeze'); freezeUntilRef.current = performance.now() + 10000; };

  const startGame = (level: Difficulty) => {
    initAudio(); playSound('click'); setLoading(false);
    setDifficulty(level); difficultyRef.current = level; 
    setGameState('PLAYING'); gameStateRef.current = 'PLAYING'; setScore(0); scoreRef.current = 0;
    lastDescentTimeRef.current = performance.now(); freezeUntilRef.current = 0; particles.current = [];
    const width = gameContainerRef.current?.clientWidth || 1000;
    const newBubbles: Bubble[] = [];
    for (let r = 0; r < DIFFICULTY_SETTINGS[level].rows; r++) 
        for (let c = 0; c < GRID_COLS; c++) if (Math.random() > 0.1) newBubbles.push(spawnBubble(r, c, width));
