        ctx.save(); ctx.font = `${radius}px serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.translate(x, y); ctx.scale(-1, 1);
        let i = ''; if (powerUp === 'bomb') i = '💣'; if (powerUp === 'freeze') i = '❄️'; if (powerUp === 'wildcard') i = '🌈';
        ctx.fillText(i, 0, 0); ctx.restore();
    }
  };

  const drawHandle = (ctx: CanvasRenderingContext2D, ax: number, ay: number, width: number, height: number, design: HandleDesign, theme: any) => {
      ctx.save();
      ctx.strokeStyle = theme.handleColor;
      ctx.lineWidth = theme.lineWidth;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.shadowBlur = theme.shadowBlur;
      ctx.shadowColor = theme.glowColor;

      ctx.beginPath();
      switch (design) {
          case 'classic':
              ctx.moveTo(ax - width, ay);
              ctx.quadraticCurveTo(ax - width, ay + height, ax, ay + height);
              ctx.quadraticCurveTo(ax + width, ay + height, ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.5);
              break;
          case 'wood':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width + 5, ay + height * 0.8);
              ctx.lineTo(ax, ay + height);
              ctx.lineTo(ax + width - 5, ay + height * 0.8);
              ctx.lineTo(ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax + 2, ay + height * 1.5);
              ctx.lineTo(ax - 2, ay + height * 2.5);
              break;
          case 'neon':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width, ay + height);
              ctx.moveTo(ax + width, ay);
              ctx.lineTo(ax + width, ay + height);
              ctx.moveTo(ax - width, ay + height);
              ctx.lineTo(ax + width, ay + height);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.8);
              break;
          case 'gold':
              ctx.moveTo(ax - width - 5, ay);
              ctx.bezierCurveTo(ax - width, ay + height, ax + width, ay + height, ax + width + 5, ay);
              ctx.moveTo(ax, ay + height);
              ctx.ellipse(ax, ay + height * 1.8, 12, 35, 0, 0, Math.PI * 2);
              break;
          case 'cyber':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width + 10, ay + height);
              ctx.lineTo(ax + width - 10, ay + height);
              ctx.lineTo(ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax - 8, ay + height + 10);
              ctx.lineTo(ax + 8, ay + height + 30);
              ctx.lineTo(ax, ay + height * 2.8);
              break;
          case 'hook':
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.5);
              ctx.moveTo(ax, ay + height);
              ctx.bezierCurveTo(ax-20, ay+height+10, ax-60, ay+40, ax-width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.bezierCurveTo(ax+20, ay+height+10, ax+60, ay+40, ax+width, ay);
              break;
      }
      ctx.stroke();
      ctx.restore();
  };

  useEffect(() => {
    if (!canvasRef.current || !fxCanvasRef.current || !gameContainerRef.current) return;
    const canvas = canvasRef.current; 
    const fxCanvas = fxCanvasRef.current; 
    const container = gameContainerRef.current;
    const ctx = canvas.getContext('2d'); 
    const fxCtx = fxCanvas.getContext('2d'); 
    if (!ctx || !fxCtx) return;

    // Critical state for preventing MediaPipe WASM Aborts
    const state = {
        isClosed: false,
        processing: false,
        lastFrameTime: 0
    };

    const updateSize = () => {
        canvas.width = fxCanvas.width = container.clientWidth; 
        canvas.height = fxCanvas.height = container.clientHeight;
        const w = canvas.width; const h = canvas.height; 
        const r = Math.min(25, Math.max(12, (w-20)/24));
        layoutRef.current = { 
            bubbleRadius: r, 
            rowHeight: r*Math.sqrt(3), 
            slingshotOffset: Math.max(160, h*0.25), 
            maxDragDist: Math.min(180, w*0.35) 
        };
        anchorPos.current = { x: w/2, y: h-layoutRef.current.slingshotOffset };
        if (!isFlying.current && !isPinching.current) ballPos.current = { ...anchorPos.current };
        bubbles.current.forEach(b => { const p = getBubblePos(b.row, b.col, w); b.x = p.x; b.y = p.y; });
    };
    updateSize();

    const onResults = (res: any) => {
      if (state.isClosed) return;
      setLoading(false); 
      if (canvas.width !== container.clientWidth) updateSize();

      ctx.clearRect(0, 0, canvas.width, canvas.height); 
      fxCtx.clearRect(0, 0, fxCanvas.width, fxCanvas.height);
      ctx.drawImage(res.image, 0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'rgba(18,18,18,0.85)'; ctx.fillRect(0,0,canvas.width,canvas.height);

      const now = performance.now(); 
      const isFrozen = now < freezeUntilRef.current;

      if (gameStateRef.current === 'PLAYING' && difficultyRef.current !== 'easy' && !isFrozen && now - lastDescentTimeRef.current > DIFFICULTY_SETTINGS[difficultyRef.current].descentInterval) {
          bubbles.current.forEach(b => { if(b.active) { b.row++; const p = getBubblePos(b.row, b.col, canvas.width); b.x = p.x; b.y = p.y; if(b.y > canvas.height-layoutRef.current.slingshotOffset) { setGameState('GAMEOVER'); gameStateRef.current = 'GAMEOVER'; } } });
          for(let c=0; c<GRID_COLS; c++) bubbles.current.push(spawnBubble(0, c, canvas.width));
          lastDescentTimeRef.current = now; updateAvailableColors();
      }

      if (gameStateRef.current === 'WIN' && Math.random() < 0.15) createFirework(Math.random()*canvas.width, Math.random()*canvas.height*0.6);

      let hp: Point | null = null; 
      let pd = 1.0;
      if (res.multiHandLandmarks?.[0]) {
        const lm = res.multiHandLandmarks[0]; const i = lm[8]; const t = lm[4];
        hp = { x: (i.x + t.x)*canvas.width/2, y: (i.y+t.y)*canvas.height/2 };
        pd = Math.hypot(i.x-t.x, i.y-t.y);
        ctx.beginPath(); ctx.arc(hp.x, hp.y, 20, 0, Math.PI*2); ctx.strokeStyle = pd < PINCH_THRESHOLD ? '#66bb6a' : '#fff'; ctx.lineWidth = 2; ctx.stroke();
      }

      if (gameStateRef.current === 'PLAYING') {
          if (hp && pd < PINCH_THRESHOLD && !isFlying.current) {
            if (!isPinching.current && Math.hypot(hp.x-ballPos.current.x, hp.y-ballPos.current.y) < 100) isPinching.current = true;
            if (isPinching.current) {
                ballPos.current = { x: hp.x, y: hp.y }; const dx = ballPos.current.x-anchorPos.current.x; const dy = ballPos.current.y-anchorPos.current.y;
                const dist = Math.hypot(dx, dy); if (dist > layoutRef.current.maxDragDist) { const a = Math.atan2(dy, dx); ballPos.current.x = anchorPos.current.x + Math.cos(a)*layoutRef.current.maxDragDist; ballPos.current.y = anchorPos.current.y + Math.sin(a)*layoutRef.current.maxDragDist; }
            }
          } else if (isPinching.current) {
            isPinching.current = false; const dx = anchorPos.current.x-ballPos.current.x; const dy = anchorPos.current.y-ballPos.current.y;
            if (Math.hypot(dx, dy) > 30) { isFlying.current = true; playSound('shoot'); flightStartTime.current = performance.now(); const v = MIN_FORCE_MULT + (MAX_FORCE_MULT-MIN_FORCE_MULT)*Math.min(Math.hypot(dx,dy)/layoutRef.current.maxDragDist,1); ballVel.current = { x: dx*v, y: dy*v }; }
            else ballPos.current = { ...anchorPos.current };
          } else if (!isFlying.current) { ballPos.current.x += (anchorPos.current.x-ballPos.current.x)*0.15; ballPos.current.y += (anchorPos.current.y-ballPos.current.y)*0.15; }
      } else ballPos.current = { ...anchorPos.current };

      if (isFlying.current) {
          if (now - flightStartTime.current > 5000) { isFlying.current = false; ballPos.current = { ...anchorPos.current }; }
          else {
              let hit = false; const steps = 5;
              for(let s=0; s<steps; s++) {
                  ballPos.current.x += ballVel.current.x/steps; ballPos.current.y += ballVel.current.y/steps;
                  if (ballPos.current.x < 10 || ballPos.current.x > canvas.width-10) ballVel.current.x *= -1;
                  if (ballPos.current.y < 10 || bubbles.current.some(b => b.active && Math.hypot(ballPos.current.x-b.x, ballPos.current.y-b.y) < layoutRef.current.bubbleRadius*1.8)) { hit = true; break; }
              }
              if (hit) {
                  isFlying.current = false; let bd = 1e9, br=0, bc=0;
                  for(let r=0; r<20; r++) for(let c=0; c<GRID_COLS; c++) {
                      const p = getBubblePos(r, c, canvas.width); if (bubbles.current.some(b => b.active && b.row===r && b.col===c)) continue;
                      const d = Math.hypot(ballPos.current.x-p.x, ballPos.current.y-p.y); if(d < bd) { bd=d; br=r; bc=c; }
                  }
                  const nb = { id: Date.now().toString(), row: br, col: bc, x: 0, y: 0, color: selectedColorRef.current, active: true };
                  const p = getBubblePos(br, bc, canvas.width); nb.x = p.x; nb.y = p.y;
                  bubbles.current.push(nb); checkMatches(nb); ballPos.current = { ...anchorPos.current };
              }
          }
      }

      bubbles.current.forEach(b => { if(b.active) drawBubble(ctx, b.x, b.y, layoutRef.current.bubbleRadius-1, b.color, b.powerUp); });
      if (isFrozen) drawMirroredText(ctx, "❄️ TIME FROZEN", canvas.width/2, 40, 'bold 20px Roboto', '#29b6f6');

      const theme = HANDLE_THEMES[handleDesignRef.current];
      if (!isFlying.current && gameStateRef.current === 'PLAYING') {
          ctx.beginPath(); ctx.moveTo(anchorPos.current.x-35, anchorPos.current.y); ctx.lineTo(ballPos.current.x, ballPos.current.y);
          ctx.moveTo(ballPos.current.x, ballPos.current.y); ctx.lineTo(anchorPos.current.x+35, anchorPos.current.y);
          ctx.strokeStyle = isPinching.current ? theme.bandColorActive : theme.bandColorIdle; ctx.lineWidth = 4; ctx.stroke();
      }
      if (gameStateRef.current !== 'MENU') drawBubble(ctx, ballPos.current.x, ballPos.current.y, layoutRef.current.bubbleRadius, selectedColorRef.current);
      drawHandle(ctx, anchorPos.current.x, anchorPos.current.y, 35, 50, handleDesignRef.current, theme);

      for (let i = particles.current.length-1; i>=0; i--) {
          const p = particles.current[i]; p.x += p.vx; p.y += p.vy; p.vy += PARTICLE_GRAVITY; p.life -= 0.05;
          if (p.life <= 0) particles.current.splice(i, 1);
          else { fxCtx.globalAlpha = p.life; fxCtx.beginPath(); fxCtx.arc(p.x, p.y, 4, 0, Math.PI*2); fxCtx.fillStyle = p.color; fxCtx.fill(); }
      }
    };

    if (!window.Hands) {
        console.error("MediaPipe Hands library not loaded.");
        return;
    }

    const hands = new window.Hands({ 
        locateFile: (f: any) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${f}` 
    });

    hands.setOptions({ 
        maxNumHands: 1, 
        modelComplexity: 1, 
        minDetectionConfidence: 0.5, 
        minTrackingConfidence: 0.5 
    });

    hands.onResults(onResults);

    const camera = new window.Camera(videoRef.current, { 
        onFrame: async () => { 
            const video = videoRef.current;
            if(!video || state.isClosed || state.processing) return;

            // Critical check: Ensure video is actually streaming and has non-zero dimensions
            if (video.readyState < 2 || video.videoWidth === 0 || video.videoHeight === 0) return;

            // Throttling to prevent WASM module saturation (max 30fps processing)
            const now = performance.now();
            if (now - state.lastFrameTime < 33) return;
            state.lastFrameTime = now;

            state.processing = true;
            try {
                // Double check if hands exists and we aren't closed before sending
                if (hands && !state.isClosed) {
                    await hands.send({ image: video }); 
                }
            } catch (e) {
                console.error("MediaPipe frame send aborted/failed:", e);
                // On a fatal WASM abort, sometimes it's best to stop the camera
                if (String(e).includes('abort')) {
                    state.isClosed = true;
                    camera.stop();
                }
            } finally {
                state.processing = false;
            }
        }, 
        width: 1280, 
        height: 720 
    });

    camera.start().catch(err => console.error("Camera failed to start:", err));

    return () => { 
        state.isClosed = true;
        camera.stop(); 
        try {
            hands.close();
        } catch (e) {
            // Silently fail if hands is already closed or destroyed
        }
    };
  }, []);

  return (
    <div className="flex flex-col md:flex-row w-full h-screen bg-[#121212] overflow-hidden font-roboto text-[#e3e3e3]">
      <div ref={gameContainerRef} className="flex-1 relative overflow-hidden bg-black/40 h-full order-1">
        <video ref={videoRef} className="absolute hidden" playsInline />
        <canvas ref={canvasRef} className="absolute inset-0 z-10" />
        <canvas ref={fxCanvasRef} className="absolute inset-0 z-[100] pointer-events-none" />

        {!loading && (gameState === 'PLAYING' || gameState === 'PAUSED') && (
            <button onClick={togglePause} className="absolute bottom-6 left-6 z-40 p-4 rounded-full bg-[#1e1e1e]/80 border border-[#444746] hover:bg-[#2d2d2d] transition-all">
                {gameState === 'PAUSED' ? <Play className="w-8 h-8 text-[#66bb6a] fill-current" /> : <Pause className="w-8 h-8 text-[#c4c7c5] fill-current" />}
            </button>
        )}

        {gameState === 'PAUSED' && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50">
                 <div className="bg-[#1e1e1e] p-8 rounded-[32px] border border-[#444746] text-center">
                     <h2 className="text-3xl font-bold text-white mb-6">Paused</h2>
                     <button onClick={togglePause} className="w-full py-3 px-8 bg-[#42a5f5] text-black rounded-xl font-bold flex items-center justify-center gap-2"> <Play className="w-5 h-5 fill-current" /> Resume </button>
                 </div>
             </div>
        )}

        {gameState === 'MENU' && !loading && (
            <div className="absolute inset-0 flex items-center justify-center bg-[#121212]/80 z-50">
                <div className="bg-[#1e1e1e] p-8 rounded-[32px] border border-[#444746] shadow-2xl max-w-md w-full text-center m-4">
                    <h1 className="text-4xl font-bold text-white mb-2">Slingshot</h1>
                    <p className="text-[#c4c7c5] mb-8 text-sm">Developed by Eleandro</p>
                    <div className="space-y-4">
                        {(Object.keys(DIFFICULTY_SETTINGS) as Difficulty[]).map(key => (
                            <button key={key} onClick={() => startGame(key)} className="w-full flex items-center justify-between p-4 rounded-2xl border border-[#444746] hover:bg-[#2d2d2d] transition-all">
                                <span className="text-white font-bold">{DIFFICULTY_SETTINGS[key].label}</span>
                                <Play className="w-5 h-5 text-[#a8c7fa]" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {gameState === 'GAMEOVER' && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/90 z-50">
                <div className="bg-[#1e1e1e] p-8 rounded-[32px] border border-[#ef5350] text-center">
                    <h2 className="text-3xl font-bold text-white mb-2">Game Over</h2>
                    <p className="text-4xl font-black text-white my-4">{score.toLocaleString()}</p>
                    <button onClick={() => setGameState('MENU')} className="w-full py-4 bg-[#ef5350] text-white rounded-full font-bold">Try Again</button>
                </div>
             </div>
        )}

        {gameState === 'WIN' && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50">
                <div className="bg-[#1e1e1e] p-8 rounded-[32px] border border-[#66bb6a] text-center">
                    <h2 className="text-4xl font-black text-white mb-2">Victory!</h2>
                    <p className="text-5xl font-black text-[#66bb6a] my-4">{score.toLocaleString()}</p>
                    <button onClick={() => setGameState('MENU')} className="w-full py-4 bg-[#66bb6a] text-white rounded-full font-bold">New Game</button>
                </div>
             </div>
        )}
      </div>

      <div className="md:w-72 md:h-full w-full h-auto border-t md:border-l bg-[#1e1e1e] border-[#444746] flex flex-row md:flex-col z-20 order-2 overflow-hidden">
          <div className="hidden md:block p-6 border-b border-[#444746]">
              <h2 className="text-xl font-bold text-white">Slingshot</h2>
              <p className="text-[10px] text-[#c4c7c5] mt-1 uppercase">By Eleandro</p>
          </div>
          <div className="flex-1 p-3 md:p-6 flex flex-row md:flex-col gap-4 overflow-x-auto no-scrollbar">
              <div className="bg-[#2d2d2d] rounded-2xl p-4 border border-[#444746] min-w-[100px]">
                  <p className="text-[10px] text-[#c4c7c5] uppercase">Score</p>
                  <p className="text-2xl font-black text-white">{score.toLocaleString()}</p>
              </div>
              <div className="flex flex-col gap-2">
                  <p className="hidden md:block text-[10px] text-[#c4c7c5] uppercase">Arsenal</p>
                  <div className="flex md:grid md:grid-cols-3 gap-2">
                      {COLOR_KEYS.map(c => (
                          <button key={c} disabled={!availableColors.includes(c)} onClick={() => setSelectedColor(c)} className={`w-10 h-10 rounded-xl transition-all ${selectedColor === c ? 'ring-2 ring-white scale-110' : ''} ${!availableColors.includes(c) ? 'opacity-20' : 'bg-[#2d2d2d]'}`}>
                              <div className="w-6 h-6 rounded-full m-auto" style={{ backgroundColor: COLOR_CONFIG[c].hex }} />
                          </button>
                      ))}
                  </div>
              </div>
              <div className="flex flex-col gap-2">
                  <p className="hidden md:block text-[10px] text-[#c4c7c5] uppercase">Sling Style</p>
                  <div className="flex md:grid md:grid-cols-3 gap-2">
                      {(Object.keys(HANDLE_THEMES) as HandleDesign[]).map(d => (
                          <button key={d} onClick={() => setHandleDesign(d)} className={`w-10 h-10 rounded-full border-2 transition-all ${handleDesign === d ? 'border-white scale-110' : 'border-[#444746]'}`} style={{ backgroundColor: HANDLE_THEMES[d].handleColor }} />
                      ))}
                  </div>
              </div>
          </div>
      </div>
    </div>
  );
};

