    activeBubbles.forEach(b => { if (b.row === 0) { queue.push(b); visited.add(b.id); } });
    let head = 0;
    while(head < queue.length){
        const current = queue[head++];
        activeBubbles.forEach(b => { if (!visited.has(b.id) && isNeighbor(current, b)) { visited.add(b.id); queue.push(b); } });
    }
    const floatingBubbles = activeBubbles.filter(b => !visited.has(b.id));
    if (floatingBubbles.length > 0) {
        let points = 0; floatingBubbles.forEach(b => { b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); points += 50; });
        playSound('pop'); scoreRef.current += points; setScore(scoreRef.current); updateAvailableColors();
    }
  };

  const triggerBomb = (centerBubble: Bubble) => {
      playSound('bomb'); const radius = layoutRef.current.bubbleRadius * 2.5; let points = 0;
      bubbles.current.forEach(b => { if (!b.active) return; const dist = Math.sqrt(Math.pow(b.x - centerBubble.x, 2) + Math.pow(b.y - centerBubble.y, 2)); if (dist < radius) { b.active = false; createExplosion(b.x, b.y, '#ffffff'); points += 50; } });
      scoreRef.current += points; setScore(scoreRef.current);
  };

  const triggerFreeze = () => { playSound('freeze'); freezeUntilRef.current = performance.now() + 10000; };

  const checkMatches = (startBubble: Bubble) => {
    const toCheck = [startBubble]; const visited = new Set<string>(); const matches: Bubble[] = [];
    const targetColor = startBubble.color; 
    while (toCheck.length > 0) {
      const current = toCheck.pop()!;
      if (visited.has(current.id)) continue;
      visited.add(current.id);
      const isMatch = current.color === targetColor || current.color === 'rainbow' || targetColor === 'rainbow';
      if (isMatch) { matches.push(current); const neighbors = bubbles.current.filter(b => b.active && !visited.has(b.id) && isNeighbor(current, b)); toCheck.push(...neighbors); }
    }
    if (matches.length >= 3) {
      let points = 0; let powerUpsTriggered: Bubble[] = [];
      matches.forEach(b => { b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); points += COLOR_CONFIG[b.color].points; if (b.powerUp) powerUpsTriggered.push(b); });
      playSound('pop'); const multiplier = matches.length > 3 ? 1.5 : 1.0; scoreRef.current += Math.floor(points * multiplier); setScore(scoreRef.current);
      powerUpsTriggered.forEach(b => { if (b.powerUp === 'bomb') triggerBomb(b); if (b.powerUp === 'freeze') triggerFreeze(); });
      dropFloatingBubbles(); checkWinCondition(); return true;
    }
    return false;
  };

  const startGame = (level: Difficulty) => {
    initAudio(); playSound('click');
    if (!gameContainerRef.current || !canvasRef.current) return;
    setDifficulty(level); difficultyRef.current = level; setGameState('PLAYING'); gameStateRef.current = 'PLAYING'; 
    setScore(0); scoreRef.current = 0; isGameOverRef.current = false; lastDescentTimeRef.current = performance.now(); freezeUntilRef.current = 0;
    particles.current = [];
    const width = gameContainerRef.current.clientWidth; const height = gameContainerRef.current.clientHeight;
    const maxRadius = 25; const radiusFromWidth = Math.floor((width - 20) / (GRID_COLS * 2)); 
    const radius = Math.min(maxRadius, Math.max(12, radiusFromWidth));
    layoutRef.current.bubbleRadius = radius; layoutRef.current.rowHeight = radius * Math.sqrt(3);
    layoutRef.current.slingshotOffset = Math.max(160, height * 0.25); layoutRef.current.maxDragDist = Math.min(180, width * 0.35);
    const anchor = { x: width / 2, y: height - layoutRef.current.slingshotOffset };
    anchorPos.current = anchor; ballPos.current = { ...anchor }; ballVel.current = { x: 0, y: 0 }; isFlying.current = false; isPinching.current = false;
    const settings = DIFFICULTY_SETTINGS[level]; const newBubbles: Bubble[] = [];
    for (let r = 0; r < settings.rows; r++) { for (let c = 0; c < (r % 2 !== 0 ? GRID_COLS - 1 : GRID_COLS); c++) { if (Math.random() > 0.1) newBubbles.push(spawnBubble(r, c, width)); } }
    bubbles.current = newBubbles; updateAvailableColors();
  };

  const addNewRow = (canvasWidth: number) => {
      let gameOver = false;
      const thresholdY = canvasRef.current ? canvasRef.current.height - layoutRef.current.slingshotOffset - layoutRef.current.bubbleRadius * 2 : 1000;
      bubbles.current.forEach(b => { if (!b.active) return; b.row++; const { x, y } = getBubblePos(b.row, b.col, canvasWidth); b.x = x; b.y = y; if (b.y > thresholdY) gameOver = true; });
      if (gameOver) { isGameOverRef.current = true; setGameState('GAMEOVER'); gameStateRef.current = 'GAMEOVER'; playSound('gameover'); return; }
      for (let c = 0; c < GRID_COLS; c++) { if (Math.random() > 0.1) bubbles.current.push(spawnBubble(0, c, canvasWidth)); }
      updateAvailableColors();
  };

  const togglePause = () => {
      playSound('click');
      if (gameState === 'PLAYING') { setGameState('PAUSED'); gameStateRef.current = 'PAUSED'; pauseStartTimeRef.current = performance.now(); } 
      else if (gameState === 'PAUSED') { setGameState('PLAYING'); gameStateRef.current = 'PLAYING'; const now = performance.now(); const pausedDuration = now - pauseStartTimeRef.current; lastDescentTimeRef.current += pausedDuration; if (freezeUntilRef.current > now) freezeUntilRef.current += pausedDuration; }
  };

  const skipTutorial = () => { playSound('click'); setShowTutorial(false); };
  const nextTutorialStep = () => { playSound('click'); if (tutorialStep < TUTORIAL_STEPS.length - 1) { setTutorialStep(prev => prev + 1); } else { setShowTutorial(false); } };
  const prevTutorialStep = () => { playSound('click'); if (tutorialStep > 0) { setTutorialStep(prev => prev - 1); } };

  const drawMirroredText = (ctx: CanvasRenderingContext2D, text: string, x: number, y: number, font: string, color: string) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(-1, 1);
    ctx.font = font; ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, 0, 0);
    ctx.restore();
  };

  const drawBubble = (ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, colorKey: BubbleColor, powerUp?: PowerUpType) => {
    const config = COLOR_CONFIG[colorKey];
    let grad;
    if (colorKey === 'rainbow') {
        grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
        grad.addColorStop(0, '#ff9999'); grad.addColorStop(0.2, '#ffff99'); grad.addColorStop(0.4, '#99ff99'); grad.addColorStop(0.6, '#99ffff'); grad.addColorStop(0.8, '#9999ff'); grad.addColorStop(1, '#ff99ff');
    } else {
        const baseColor = config.hex; grad = ctx.createRadialGradient(x - radius * 0.3, y - radius * 0.3, radius * 0.1, x, y, radius);
        grad.addColorStop(0, '#ffffff'); grad.addColorStop(0.2, baseColor); grad.addColorStop(1, adjustColor(baseColor, -60)); 
    }
    ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.fillStyle = grad; ctx.fill();
    ctx.strokeStyle = colorKey === 'rainbow' ? 'white' : adjustColor(config.hex, -80); ctx.lineWidth = 1; ctx.stroke();

    // Highlight
    ctx.beginPath(); ctx.ellipse(x - radius * 0.3, y - radius * 0.35, radius * 0.25, radius * 0.15, Math.PI / 4, 0, Math.PI * 2); ctx.fillStyle = 'rgba(255, 255, 255, 0.3)'; ctx.fill();

    if (powerUp) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(-1, 1); // Un-mirror for the emoji
        ctx.font = `${radius}px serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        let icon = ''; if (powerUp === 'bomb') icon = '💣'; if (powerUp === 'freeze') icon = '❄️'; if (powerUp === 'wildcard') icon = '🌈';
        ctx.fillText(icon, 0, 2);
        ctx.restore();
    }
  };

  const drawHandle = (ctx: CanvasRenderingContext2D, ax: number, ay: number, hWidth: number, hHeight: number, design: HandleDesign, theme: any, canvasHeight: number) => {
    ctx.save(); 
    ctx.shadowBlur = theme.shadowBlur; ctx.shadowColor = theme.glowColor; ctx.strokeStyle = theme.handleColor; ctx.lineWidth = 12; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.beginPath();
    if (design === 'hook') {
      ctx.moveTo(ax, ay + hHeight); ctx.lineTo(ax, canvasHeight); ctx.moveTo(ax, ay + hHeight); ctx.bezierCurveTo(ax - 20, ay + hHeight + 10, ax - 60, ay + 40, ax - hWidth, ay); ctx.moveTo(ax, ay + hHeight); ctx.bezierCurveTo(ax + 20, ay + hHeight + 10, ax + 60, ay + 40, ax + hWidth, ay);
