            }
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)'; ctx.setLineDash([4, 4]); ctx.lineWidth = 2; ctx.stroke(); ctx.setLineDash([]);
         }
      }

      const currentTheme = HANDLE_THEMES[handleDesignRef.current];
      const bandColor = isPinching.current ? currentTheme.bandColorActive : currentTheme.bandColorIdle;

      if (!isFlying.current && gameStateRef.current !== 'MENU' && gameStateRef.current !== 'GAMEOVER') {
        ctx.beginPath(); ctx.moveTo(anchorPos.current.x - 35, anchorPos.current.y); ctx.lineTo(ballPos.current.x, ballPos.current.y); ctx.lineWidth = 4; ctx.strokeStyle = bandColor; ctx.lineCap = 'round'; ctx.stroke();
      }
      if (gameStateRef.current !== 'MENU' && gameStateRef.current !== 'GAMEOVER') {
        drawBubble(ctx, ballPos.current.x, ballPos.current.y, bubbleRadius, selectedColorRef.current);
      }
      if (!isFlying.current && gameStateRef.current !== 'MENU' && gameStateRef.current !== 'GAMEOVER') {
        ctx.beginPath(); ctx.moveTo(ballPos.current.x, ballPos.current.y); ctx.lineTo(anchorPos.current.x + 35, anchorPos.current.y); ctx.lineWidth = 4; ctx.strokeStyle = bandColor; ctx.lineCap = 'round'; ctx.stroke();
