const PINCH_THRESHOLD = 0.05;
const GRAVITY = 0.0; 
const FRICTION = 0.998; 
const PARTICLE_GRAVITY = 0.15; 

const GRID_COLS = 12;
const GRID_ROWS = 8;

const MIN_FORCE_MULT = 0.15;
const MAX_FORCE_MULT = 0.45;

const POWERUP_CHANCE = 0.25; 

