    cyber: { id: 'cyber', label: 'Cyber', handleColor: '#1a1a1a', bandColorActive: '#00e676', bandColorIdle: 'rgba(0,230,118,0.3)', glowColor: '#00c853', shadowBlur: 20, lineWidth: 6 }
};

const COLOR_CONFIG: Record<BubbleColor, { hex: string, points: number, label: string }> = {
  red:    { hex: '#ef5350', points: 100, label: 'Red' },
  blue:   { hex: '#42a5f5', points: 150, label: 'Blue' },
  green:  { hex: '#66bb6a', points: 200, label: 'Green' },
  yellow: { hex: '#ffee58', points: 250, label: 'Yellow' },
  purple: { hex: '#ab47bc', points: 300, label: 'Purple' },
  orange: { hex: '#ffa726', points: 500, label: 'Orange' },
  rainbow:{ hex: '#ffffff', points: 500, label: 'Wildcard' }
};

const COLOR_KEYS: BubbleColor[] = ['red', 'blue', 'green', 'yellow', 'purple', 'orange'];

const adjustColor = (color: string, amount: number) => {
    const hex = color.replace('#', '');
    const r = Math.max(0, Math.min(255, parseInt(hex.substring(0, 2), 16) + amount));
    const g = Math.max(0, Math.min(255, parseInt(hex.substring(2, 4), 16) + amount));
    const b = Math.max(0, Math.min(255, parseInt(hex.substring(4, 6), 16) + amount));
    const componentToHex = (c: number) => {
        const hexVal = c.toString(16);
        return hexVal.length === 1 ? "0" + hexVal : hexVal;
    };
    return "#" + componentToHex(r) + componentToHex(g) + componentToHex(b);
};

const GeminiSlingshot: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fxCanvasRef = useRef<HTMLCanvasElement>(null);
  const gameContainerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const layoutRef = useRef({ bubbleRadius: 22, rowHeight: 38, slingshotOffset: 220, maxDragDist: 180 });
  const ballPos = useRef<Point>({ x: 0, y: 0 });
  const ballVel = useRef<Point>({ x: 0, y: 0 });
  const anchorPos = useRef<Point>({ x: 0, y: 0 });
  const isPinching = useRef<boolean>(false);
  const isFlying = useRef<boolean>(false);
  const flightStartTime = useRef<number>(0);
  const bubbles = useRef<Bubble[]>([]);
  const particles = useRef<Particle[]>([]);
  const scoreRef = useRef<number>(0);
  const lastDescentTimeRef = useRef<number>(0);
  const freezeUntilRef = useRef<number>(0);
  const selectedColorRef = useRef<BubbleColor>('red');
  const gameStateRef = useRef<'MENU' | 'PLAYING' | 'GAMEOVER' | 'WIN' | 'PAUSED'>('MENU');
  const difficultyRef = useRef<Difficulty>('medium');
  const handleDesignRef = useRef<HandleDesign>('hook'); 

  const [loading, setLoading] = useState(true);
  const [score, setScore] = useState(0);
  const [selectedColor, setSelectedColor] = useState<BubbleColor>('red');
  const [availableColors, setAvailableColors] = useState<BubbleColor[]>([]);
  const [gameState, setGameState] = useState<'MENU' | 'PLAYING' | 'GAMEOVER' | 'WIN' | 'PAUSED'>('MENU');
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [handleDesign, setHandleDesign] = useState<HandleDesign>('hook'); 

  useEffect(() => { selectedColorRef.current = selectedColor; }, [selectedColor]);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);
  useEffect(() => { difficultyRef.current = difficulty; }, [difficulty]);
  useEffect(() => { handleDesignRef.current = handleDesign; }, [handleDesign]);

  const initAudio = useCallback(() => {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      if (audioCtxRef.current.state === 'suspended') audioCtxRef.current.resume();
  }, []);

  const playSound = useCallback((type: 'shoot' | 'pop' | 'click' | 'gameover' | 'bomb' | 'freeze' | 'win') => {
      if (!audioCtxRef.current) return;
      const ctx = audioCtxRef.current; const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination); const now = ctx.currentTime;
      if (type === 'shoot') { osc.type = 'triangle'; osc.frequency.setValueAtTime(150, now); osc.frequency.exponentialRampToValueAtTime(600, now + 0.1); gain.gain.setValueAtTime(0.3, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.15); osc.start(now); osc.stop(now + 0.15); }
      else if (type === 'pop') { osc.type = 'sine'; osc.frequency.setValueAtTime(800 + Math.random() * 200, now); osc.frequency.exponentialRampToValueAtTime(100, now + 0.1); gain.gain.setValueAtTime(0.15, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1); osc.start(now); osc.stop(now + 0.1); }
      else if (type === 'click') { osc.type = 'square'; osc.frequency.setValueAtTime(600, now); gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05); osc.start(now); osc.stop(now + 0.05); }
      else if (type === 'bomb') { osc.type = 'sawtooth'; osc.frequency.setValueAtTime(100, now); osc.frequency.exponentialRampToValueAtTime(0.01, now + 0.5); gain.gain.setValueAtTime(0.5, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5); osc.start(now); osc.stop(now + 0.5); }
      else if (type === 'freeze') { osc.type = 'sine'; osc.frequency.setValueAtTime(1200, now); osc.frequency.linearRampToValueAtTime(2000, now + 0.5); gain.gain.setValueAtTime(0.2, now); gain.gain.linearRampToValueAtTime(0, now + 0.5); osc.start(now); osc.stop(now + 0.5); }
      else if (type === 'win') { playTone(523, now, 0.2); playTone(659, now+0.2, 0.2); playTone(783, now+0.4, 0.2); playTone(1046, now+0.6, 0.8); }
      function playTone(f: number, s: number, d: number) { const o = ctx.createOscillator(); const g = ctx.createGain(); o.connect(g); g.connect(ctx.destination); o.frequency.setValueAtTime(f, s); g.gain.setValueAtTime(0.2, s); g.gain.linearRampToValueAtTime(0, s+d); o.start(s); o.stop(s+d); }
  }, []);

  const getBubblePos = (row: number, col: number, width: number) => {
    const { bubbleRadius, rowHeight } = layoutRef.current;
    const gridWidth = GRID_COLS * bubbleRadius * 2;
    const xOffset = (width - gridWidth) / 2 + bubbleRadius;
    const x = xOffset + col * (bubbleRadius * 2) + (row % 2 !== 0 ? bubbleRadius : 0);
    const y = bubbleRadius + row * rowHeight;
    return { x, y };
  };

  const updateAvailableColors = () => {
    const activeColors = new Set<BubbleColor>();
    bubbles.current.forEach(b => { if (b.active && b.color !== 'rainbow') activeColors.add(b.color); });
    setAvailableColors(Array.from(activeColors));
    if (!activeColors.has(selectedColorRef.current) && activeColors.size > 0) {
        const next = Array.from(activeColors)[0]; setSelectedColor(next); selectedColorRef.current = next; 
    }
  };

  const isNeighbor = (a: Bubble, b: Bubble) => {
    const dr = b.row - a.row; const dc = b.col - a.col;
    if (Math.abs(dr) > 1) return false;
    if (dr === 0) return Math.abs(dc) === 1;
    if (a.row % 2 !== 0) return dc === 0 || dc === 1;
    else return dc === -1 || dc === 0;
  };

  const createExplosion = (x: number, y: number, color: string) => {
    for (let i = 0; i < 15; i++) particles.current.push({ x, y, vx: (Math.random()-0.5)*12, vy: (Math.random()-0.5)*12, life: 1.0, color });
  };

  const createFirework = (x: number, y: number) => {
      const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
      for (let i = 0; i < 50; i++) {
          const a = Math.random()*Math.PI*2; const s = Math.random()*8+3;
          particles.current.push({ x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s, life: 1.5+Math.random(), color: colors[Math.floor(Math.random()*colors.length)] });
      }
  };

  const spawnBubble = (row: number, col: number, width: number): Bubble => {
      const { x, y } = getBubblePos(row, col, width);
      let color = COLOR_KEYS[Math.floor(Math.random() * COLOR_KEYS.length)];
      let powerUp: PowerUpType | undefined = undefined;
      if (Math.random() < POWERUP_CHANCE) {
          const r = Math.random();
          if (r < 0.33) powerUp = 'bomb';
          else if (r < 0.66) powerUp = 'freeze';
          else { powerUp = 'wildcard'; color = 'rainbow'; }
      }
      return { id: `${row}-${col}-${Date.now()}-${Math.random()}`, row, col, x, y, color, active: true, powerUp };
  };

  const checkMatches = (startBubble: Bubble) => {
    const toCheck = [startBubble]; const visited = new Set<string>(); const matches: Bubble[] = [];
    const targetColor = startBubble.color; 
    while (toCheck.length > 0) {
      const current = toCheck.pop()!;
      if (visited.has(current.id)) continue;
      visited.add(current.id);
      if (current.color === targetColor || current.color === 'rainbow' || targetColor === 'rainbow') {
        matches.push(current);
        toCheck.push(...bubbles.current.filter(b => b.active && !visited.has(b.id) && isNeighbor(current, b)));
      }
    }
    if (matches.length >= 3) {
      matches.forEach(b => { 
          b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); 
          scoreRef.current += COLOR_CONFIG[b.color].points;
          if (b.powerUp === 'bomb') triggerBomb(b);
          if (b.powerUp === 'freeze') triggerFreeze();
      });
      playSound('pop'); setScore(scoreRef.current); dropFloating(); updateAvailableColors();
      if (bubbles.current.filter(b => b.active).length === 0) { setGameState('WIN'); gameStateRef.current = 'WIN'; playSound('win'); }
      return true;
    }
    return false;
  };

  const dropFloating = () => {
    const active = bubbles.current.filter(b => b.active); if (active.length === 0) return;
    const visited = new Set<string>(); const queue: Bubble[] = active.filter(b => b.row === 0);
    queue.forEach(b => visited.add(b.id)); let head = 0;
    while(head < queue.length){
        const curr = queue[head++];
        active.filter(b => !visited.has(b.id) && isNeighbor(curr, b)).forEach(b => { visited.add(b.id); queue.push(b); });
    }
    active.filter(b => !visited.has(b.id)).forEach(b => { b.active = false; createExplosion(b.x, b.y, COLOR_CONFIG[b.color].hex); scoreRef.current += 50; });
  };

  const triggerBomb = (b: Bubble) => {
      playSound('bomb'); const r = layoutRef.current.bubbleRadius * 2.5;
      bubbles.current.filter(nb => nb.active && Math.hypot(nb.x-b.x, nb.y-b.y) < r).forEach(nb => { nb.active = false; createExplosion(nb.x, nb.y, '#fff'); scoreRef.current += 50; });
  };

  const triggerFreeze = () => { playSound('freeze'); freezeUntilRef.current = performance.now() + 10000; };

  const startGame = (level: Difficulty) => {
    initAudio(); playSound('click'); setLoading(false);
    setDifficulty(level); difficultyRef.current = level; 
    setGameState('PLAYING'); gameStateRef.current = 'PLAYING'; setScore(0); scoreRef.current = 0;
    lastDescentTimeRef.current = performance.now(); freezeUntilRef.current = 0; particles.current = [];
    const width = gameContainerRef.current?.clientWidth || 1000;
    const newBubbles: Bubble[] = [];
    for (let r = 0; r < DIFFICULTY_SETTINGS[level].rows; r++) 
        for (let c = 0; c < GRID_COLS; c++) if (Math.random() > 0.1) newBubbles.push(spawnBubble(r, c, width));
    bubbles.current = newBubbles; updateAvailableColors();
  };

  const togglePause = () => {
      playSound('click');
      if (gameState === 'PLAYING') { setGameState('PAUSED'); gameStateRef.current = 'PAUSED'; }
      else if (gameState === 'PAUSED') { setGameState('PLAYING'); gameStateRef.current = 'PLAYING'; lastDescentTimeRef.current = performance.now(); }
  };

  const drawMirroredText = (ctx: CanvasRenderingContext2D, text: string, x: number, y: number, font: string, color: string) => {
    ctx.save(); ctx.font = font; ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.translate(x, y); ctx.scale(-1, 1); ctx.fillText(text, 0, 0); ctx.restore();
  };

  const drawBubble = (ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, colorKey: BubbleColor, powerUp?: PowerUpType) => {
    const config = COLOR_CONFIG[colorKey];
    let grad = ctx.createRadialGradient(x-radius*0.3, y-radius*0.3, radius*0.1, x, y, radius);
    grad.addColorStop(0, '#fff'); grad.addColorStop(0.2, config.hex); grad.addColorStop(1, adjustColor(config.hex, -60));
    ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fillStyle = grad; ctx.fill();
    if (powerUp) {
        ctx.save(); ctx.font = `${radius}px serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.translate(x, y); ctx.scale(-1, 1);
        let icon = ''; if (powerUp === 'bomb') icon = '💣'; if (powerUp === 'freeze') icon = '❄️'; if (powerUp === 'wildcard') icon = '🌈';
        ctx.fillText(icon, 0, 0); ctx.restore();
    }
  };

  const drawHandle = (ctx: CanvasRenderingContext2D, ax: number, ay: number, width: number, height: number, design: HandleDesign, theme: any) => {
      ctx.save();
      ctx.strokeStyle = theme.handleColor;
      ctx.lineWidth = theme.lineWidth;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.shadowBlur = theme.shadowBlur;
      ctx.shadowColor = theme.glowColor;

      ctx.beginPath();
      switch (design) {
          case 'classic':
              ctx.moveTo(ax - width, ay);
              ctx.quadraticCurveTo(ax - width, ay + height, ax, ay + height);
              ctx.quadraticCurveTo(ax + width, ay + height, ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.5);
              break;
          case 'wood':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width + 5, ay + height * 0.8);
              ctx.lineTo(ax, ay + height);
              ctx.lineTo(ax + width - 5, ay + height * 0.8);
              ctx.lineTo(ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax + 2, ay + height * 1.5);
              ctx.lineTo(ax - 2, ay + height * 2.5);
              break;
          case 'neon':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width, ay + height);
              ctx.moveTo(ax + width, ay);
              ctx.lineTo(ax + width, ay + height);
              ctx.moveTo(ax - width, ay + height);
              ctx.lineTo(ax + width, ay + height);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.8);
              break;
          case 'gold':
              ctx.moveTo(ax - width - 5, ay);
              ctx.bezierCurveTo(ax - width, ay + height, ax + width, ay + height, ax + width + 5, ay);
              ctx.moveTo(ax, ay + height);
              ctx.ellipse(ax, ay + height * 1.8, 12, 35, 0, 0, Math.PI * 2);
              break;
          case 'cyber':
              ctx.moveTo(ax - width, ay);
              ctx.lineTo(ax - width + 10, ay + height);
              ctx.lineTo(ax + width - 10, ay + height);
              ctx.lineTo(ax + width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax - 8, ay + height + 10);
              ctx.lineTo(ax + 8, ay + height + 30);
              ctx.lineTo(ax, ay + height * 2.8);
              break;
          case 'hook':
              ctx.moveTo(ax, ay + height);
              ctx.lineTo(ax, ay + height * 2.5);
              ctx.moveTo(ax, ay + height);
              ctx.bezierCurveTo(ax-20, ay+height+10, ax-60, ay+40, ax-width, ay);
              ctx.moveTo(ax, ay + height);
              ctx.bezierCurveTo(ax+20, ay+height+10, ax+60, ay+40, ax+width, ay);
              break;
      }
      ctx.stroke();
      ctx.restore();
  };

  useEffect(() => {
    if (!canvasRef.current || !fxCanvasRef.current || !gameContainerRef.current) return;
    const canvas = canvasRef.current; const fxCanvas = fxCanvasRef.current; const container = gameContainerRef.current;
    const ctx = canvas.getContext('2d'); const fxCtx = fxCanvas.getContext('2d'); if (!ctx || !fxCtx) return;

    // Safety flags to prevent MediaPipe Abort errors
    let isClosed = false;
    let processing = false;

    const updateSize = () => {
        canvas.width = fxCanvas.width = container.clientWidth; canvas.height = fxCanvas.height = container.clientHeight;
        const w = canvas.width; const h = canvas.height; const r = Math.min(25, Math.max(12, (w-20)/24));
        layoutRef.current = { bubbleRadius: r, rowHeight: r*Math.sqrt(3), slingshotOffset: Math.max(160, h*0.25), maxDragDist: Math.min(180, w*0.35) };
        anchorPos.current = { x: w/2, y: h-layoutRef.current.slingshotOffset };
        if (!isFlying.current && !isPinching.current) ballPos.current = { ...anchorPos.current };
        bubbles.current.forEach(b => { const p = getBubblePos(b.row, b.col, w); b.x = p.x; b.y = p.y; });
    };
    updateSize();

    const onResults = (res: any) => {
      if (isClosed) return;
      setLoading(false); 
      if (canvas.width !== container.clientWidth) updateSize();

      ctx.clearRect(0, 0, canvas.width, canvas.height); 
      fxCtx.clearRect(0, 0, fxCanvas.width, fxCanvas.height);
      ctx.drawImage(res.image, 0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'rgba(18,18,18,0.85)'; ctx.fillRect(0,0,canvas.width,canvas.height);

      const now = performance.now(); 
      const isFrozen = now < freezeUntilRef.current;

      if (gameStateRef.current === 'PLAYING' && difficultyRef.current !== 'easy' && !isFrozen && now - lastDescentTimeRef.current > DIFFICULTY_SETTINGS[difficultyRef.current].descentInterval) {
          bubbles.current.forEach(b => { if(b.active) { b.row++; const p = getBubblePos(b.row, b.col, canvas.width); b.x = p.x; b.y = p.y; if(b.y > canvas.height-layoutRef.current.slingshotOffset) { setGameState('GAMEOVER'); gameStateRef.current = 'GAMEOVER'; } } });
          for(let c=0; c<GRID_COLS; c++) bubbles.current.push(spawnBubble(0, c, canvas.width));
          lastDescentTimeRef.current = now; updateAvailableColors();
      }

      if (gameStateRef.current === 'WIN' && Math.random() < 0.15) createFirework(Math.random()*canvas.width, Math.random()*canvas.height*0.6);

      let hp: Point | null = null; 
      let pd = 1.0;
      if (res.multiHandLandmarks?.[0]) {
        const lm = res.multiHandLandmarks[0]; const i = lm[8]; const t = lm[4];
        hp = { x: (i.x + t.x)*canvas.width/2, y: (i.y+t.y)*canvas.height/2 };
        pd = Math.hypot(i.x-t.x, i.y-t.y);
        ctx.beginPath(); ctx.arc(hp.x, hp.y, 20, 0, Math.PI*2); ctx.strokeStyle = pd < PINCH_THRESHOLD ? '#66bb6a' : '#fff'; ctx.lineWidth = 2; ctx.stroke();
      }

      if (gameStateRef.current === 'PLAYING') {
          if (hp && pd < PINCH_THRESHOLD && !isFlying.current) {
            if (!isPinching.current && Math.hypot(hp.x-ballPos.current.x, hp.y-ballPos.current.y) < 100) isPinching.current = true;
            if (isPinching.current) {
                ballPos.current = { x: hp.x, y: hp.y }; const dx = ballPos.current.x-anchorPos.current.x; const dy = ballPos.current.y-anchorPos.current.y;
                const dist = Math.hypot(dx, dy); if (dist > layoutRef.current.maxDragDist) { const a = Math.atan2(dy, dx); ballPos.current.x = anchorPos.current.x + Math.cos(a)*layoutRef.current.maxDragDist; ballPos.current.y = anchorPos.current.y + Math.sin(a)*layoutRef.current.maxDragDist; }
            }
          } else if (isPinching.current) {
            isPinching.current = false; const dx = anchorPos.current.x-ballPos.current.x; const dy = anchorPos.current.y-ballPos.current.y;
            if (Math.hypot(dx, dy) > 30) { isFlying.current = true; playSound('shoot'); flightStartTime.current = performance.now(); const v = MIN_FORCE_MULT + (MAX_FORCE_MULT-MIN_FORCE_MULT)*Math.min(Math.hypot(dx,dy)/layoutRef.current.maxDragDist,1); ballVel.current = { x: dx*v, y: dy*v }; }
            else ballPos.current = { ...anchorPos.current };
          } else if (!isFlying.current) { ballPos.current.x += (anchorPos.current.x-ballPos.current.x)*0.15; ballPos.current.y += (anchorPos.current.y-ballPos.current.y)*0.15; }
      } else ballPos.current = { ...anchorPos.current };

      if (isFlying.current) {
          if (now - flightStartTime.current > 5000) { isFlying.current = false; ballPos.current = { ...anchorPos.current }; }
          else {
              let hit = false; const steps = 5;
              for(let s=0; s<steps; s++) {
                  ballPos.current.x += ballVel.current.x/steps; ballPos.current.y += ballVel.current.y/steps;
                  if (ballPos.current.x < 10 || ballPos.current.x > canvas.width-10) ballVel.current.x *= -1;
                  if (ballPos.current.y < 10 || bubbles.current.some(b => b.active && Math.hypot(ballPos.current.x-b.x, ballPos.current.y-b.y) < layoutRef.current.bubbleRadius*1.8)) { hit = true; break; }
              }
              if (hit) {
                  isFlying.current = false; let bd = 1e9, br=0, bc=0;
                  for(let r=0; r<20; r++) for(let c=0; c<GRID_COLS; c++) {
                      const p = getBubblePos(r, c, canvas.width); if (bubbles.current.some(b => b.active && b.row===r && b.col===c)) continue;
                      const d = Math.hypot(ballPos.current.x-p.x, ballPos.current.y-p.y); if(d < bd) { bd=d; br=r; bc=c; }
                  }
                  const nb = { id: Date.now().toString(), row: br, col: bc, x: 0, y: 0, color: selectedColorRef.current, active: true };
                  const p = getBubblePos(br, bc, canvas.width); nb.x = p.x; nb.y = p.y;
                  bubbles.current.push(nb); checkMatches(nb); ballPos.current = { ...anchorPos.current };
              }
          }
      }

      bubbles.current.forEach(b => { if(b.active) drawBubble(ctx, b.x, b.y, layoutRef.current.bubbleRadius-1, b.color, b.powerUp); });
      if (isFrozen) drawMirroredText(ctx, "❄️ TIME FROZEN", canvas.width/2, 40, 'bold 20px Roboto', '#29b6f6');

      const theme = HANDLE_THEMES[handleDesignRef.current];
      if (!isFlying.current && gameStateRef.current === 'PLAYING') {
          ctx.beginPath(); ctx.moveTo(anchorPos.current.x-35, anchorPos.current.y); ctx.lineTo(ballPos.current.x, ballPos.current.y);
          ctx.moveTo(ballPos.current.x, ballPos.current.y); ctx.lineTo(anchorPos.current.x+35, anchorPos.current.y);
          ctx.strokeStyle = isPinching.current ? theme.bandColorActive : theme.bandColorIdle; ctx.lineWidth = 4; ctx.stroke();
      }
      if (gameStateRef.current !== 'MENU') drawBubble(ctx, ballPos.current.x, ballPos.current.y, layoutRef.current.bubbleRadius, selectedColorRef.current);
      drawHandle(ctx, anchorPos.current.x, anchorPos.current.y, 35, 50, handleDesignRef.current, theme);

      for (let i = particles.current.length-1; i>=0; i--) {
          const p = particles.current[i]; p.x += p.vx; p.y += p.vy; p.vy += PARTICLE_GRAVITY; p.life -= 0.05;
          if (p.life <= 0) particles.current.splice(i, 1);
