    hands.setOptions({ maxNumHands: 1, minDetectionConfidence: 0.5 }); hands.onResults(onResults);

    const cam = new window.Camera(videoRef.current, { 
        onFrame: async () => { 
            const video = videoRef.current;
            if(!video || isClosed || processing) return;
            // CRITICAL: Prevent Aborted errors by ensuring video is ready and has non-zero dimensions
            if (video.readyState < 2 || video.videoWidth === 0 || video.videoHeight === 0) return;

            processing = true;
            try {
                await hands.send({ image: video }); 
            } catch (e) {
                console.error("MediaPipe error during hands.send:", e);
            } finally {
                processing = false;
            }
        }, 
        width: 1280, 
        height: 720 
    });

    cam.start().catch((err: any) => {
        console.error("Camera failed to start:", err);
        setLoading(false);
    });

    return () => { 
        isClosed = true;
        cam.stop(); 
        try {
            hands.close();
        } catch (e) {}
    };
  }, []);

  return (
    <div className="flex flex-col md:flex-row w-full h-screen bg-[#121212] overflow-hidden font-roboto text-[#e3e3e3]">
      <div ref={gameContainerRef} className="flex-1 relative overflow-hidden bg-black/40 h-full order-1">
        <video ref={videoRef} className="absolute hidden" playsInline />
        <canvas ref={canvasRef} className="absolute inset-0 z-10" />
        <canvas ref={fxCanvasRef} className="absolute inset-0 z-[100] pointer-events-none" />

        {loading && (
